    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "TDF toxicity symptoms present",
    "message": "Guidelines list exhaustion, extreme fatigue, muscle cramps, and headache as presenting signs of TDF toxicity including lactic acidosis and Fanconi syndrome. Patient reports mild fatigue over 2 months. While she attributes this to work schedule, TDF has been used for 3 years and renal function is declining with proteinuria, making TDF toxicity a plausible contributor. Against drug attribution: fatigue is non-specific and her busy schedule provides an alternative explanation. No muscle cramps or headache are reported. Given eGFR 52, TDF should be discontinued regardless.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Evaluate for TDF toxicity including LFTs, RFTs, and serum lactate. Discontinue TDF and switch to TAF given renal impairment.",
